    ...
  ],
  "shouldGenerate": true,                         // boolean
  "ca": "-----BEGIN CERTIFICATE-----\nMIIDzTCCArWgAwIBAgIUI...\n-----END CERTIFICATE-----",                 // string [ 1 .. 2000000 ] characters
